{
  "technical_and_design_decisions": [
    "Adopt Markdown/AsciiDoc format for migrating wiki pages into the project repository under standard doc directories.",
    "Extend Spring XD DSL configuration files to support default Hadoop Namenode URIs and related HA configurations.",
    "Implement a dedicated passthrough tasklet/step in the jdbchdfs batch job to bypass chunk reader/writer overhead.",
    "Decouple JobExecution and StepExecution context handling in Spring Batch to prevent ClassLoader and serialization leaks, then update Spring XD dependency and refactor existing workaround (XD-2486).",
    "Enhance Spring XD module deployment logic to properly scan and instantiate Java Config-based custom batch job modules.",
    "Design an abstract Runtime SPI layer for container orchestration in Spring XD, decoupling the Receptor API as a pluggable backend implementation.",
    "Add shortDescription metadata field across all standard Spring XD module definitions and update doc generation scripts.",
    "Extend the Shell processor module to retrieve Python script resources from HDFS URIs before launching execution in Cloud Foundry environments."
  ],
  "assumptions": [
    "A single developer will execute all implementation, refactoring, testing, and documentation activities.",
    "A local or containerized Hadoop ecosystem and Cloud Foundry environment are available for integration testing.",
    "Upstream Spring Batch changes required for U4 can be developed or integrated within the context of this work package.",
    "Existing automated test suites and build scripts (Gradle/Maven) are operational and reusable."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "U1: Wiki to Repository Migration",
      "activity_description": "Export current wiki content, convert formatting to standard documentation (AsciiDoc/Markdown), integrate into the main repository, and configure documentation tagging in the build pipeline.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "U2: Hadoop Namenode Config Integration in DSL",
      "activity_description": "Modify Spring XD DSL configuration loader to auto-wire Namenode properties from configuration files, eliminating manual configuration per DSL session.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "U3: Passthrough jdbchdfs Batch Job Implementation",
      "activity_description": "Create a passthrough batch step implementation for jdbchdfs job template to stream data directly without chunk-based read/write processing overhead.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "U4: Execution Context Decoupling & Batch Workaround Refactoring",
      "activity_description": "Refactor Spring Batch execution context lifecycle to avoid ClassLoader and serialization issues, upgrade Spring XD Batch dependency, and remove XD-2486 workaround.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "U5: Custom Java Config Job Module Fix",
      "activity_description": "Fix job module deployment scanner to recognize and register custom job archives defined via Java Config instead of XML configuration files.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "U6: Pluggable Runtime SPI Design (Diego/Lattice PoC)",
      "activity_description": "Architect a generic pluggable orchestration SPI interface for Spring XD, refactoring Diego/Lattice Receptor integration into a pluggable SPI implementation.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "U7: Module Documentation Short Description Updates",
      "activity_description": "Audit all existing module descriptors and documentation files to insert shortDescription fields across all module categories.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "U8: HDFS Python Script Hosting for Shell Processor",
      "activity_description": "Enhance XD shell processor module to fetch Python scripts hosted on HDFS dynamically before launching Py runtime on Cloud Foundry.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "Integration Testing and Verification",
      "activity_description": "Perform comprehensive end-to-end testing, integration verification across all modules, and regression testing prior to completion.",
      "most_likely_effort": 20
    }
  ],
  "reported_total": {
    "most_likely_effort": 160
  }
}
